namespace sv_9998f251ca3d436eb504172a1db02f07.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_9998f251ca3d436eb504172a1db02f07.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
            </div>
        }
    </main>
</div>

@* ===== Profile Section ===== *@
@{
    RenderFragment ProfileSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                <img src="@editProfile!.AvatarUrl" alt="Avatar" onerror="this.style.display='none'" />
                <p class="avatar-url">@editProfile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
            </div>

            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="editProfile.AvatarUrl" />
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ===== Notifications Section ===== *@
@{
    RenderFragment NotificationsSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications!.EmailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.PushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channels-list">
                @foreach (var channel in availableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@editNotifications.MutedChannels.Contains(ch)"
                               @onchange="(e) => ToggleMutedChannel(ch, (bool)e.Value!)" />
                        <span>@ch</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* ===== Security Section ===== *@
@{
    RenderFragment SecuritySection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
                </button>

                @if (passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(passwordError))
                        {
                            <p class="error-text">@passwordError</p>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" checked="@securitySettings!.TwoFactorEnabled" disabled />
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-on" : "status-off")">
                        @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </label>
            </div>

            @if (securitySettings.LastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            <div class="sessions-table-container">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != securitySettings.Sessions.First())
                                    {
                                        <button class="btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            @if (sessionToRevoke is not null)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal" @onclick:stopPropagation="true">
                        <h3>Confirm Session Revocation</h3>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ===== Appearance Section ===== *@
@{
    RenderFragment AppearanceSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label><input type="radio" name="theme" value="Light" checked="@(editAppearance!.Theme == "Light")" @onchange='() => editAppearance.Theme = "Light"' /> Light</label>
                    <label><input type="radio" name="theme" value="Dark" checked="@(editAppearance.Theme == "Dark")" @onchange='() => editAppearance.Theme = "Dark"' /> Dark</label>
                    <label><input type="radio" name="theme" value="System" checked="@(editAppearance.Theme == "System")" @onchange='() => editAppearance.Theme = "System"' /> System</label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label><input type="radio" name="fontSize" value="Small" checked="@(editAppearance.FontSize == "Small")" @onchange='() => editAppearance.FontSize = "Small"' /> Small</label>
                    <label><input type="radio" name="fontSize" value="Medium" checked="@(editAppearance.FontSize == "Medium")" @onchange='() => editAppearance.FontSize = "Medium"' /> Medium</label>
                    <label><input type="radio" name="fontSize" value="Large" checked="@(editAppearance.FontSize == "Large")" @onchange='() => editAppearance.FontSize = "Large"' /> Large</label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="editAppearance.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <h3>Live Preview</h3>
            <div class="live-preview @(editAppearance.Theme == "Dark" ? "preview-dark" : "preview-light") @(editAppearance.CompactMode ? "preview-compact" : "")"
                 style="font-size: @GetPreviewFontSize()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is how your content will look with the selected settings. The theme is <strong>@editAppearance.Theme</strong>, font size is <strong>@editAppearance.FontSize</strong>, and compact mode is <strong>@(editAppearance.CompactMode ? "on" : "off")</strong>.</p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string? toastMessage;
    private string toastType = "toast-success";
    private System.Timers.Timer? toastTimer;

    // Profile
    private UserProfile? savedProfile;
    private EditableProfile? editProfile;

    // Notifications
    private NotificationPrefs? savedNotifications;
    private EditableNotifications? editNotifications;
    private List<string> availableChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security
    private SecuritySettings? securitySettings;
    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? savedAppearance;
    private EditableAppearance? editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        savedProfile = await profileTask;
        editProfile = new EditableProfile(savedProfile);

        savedNotifications = await notifTask;
        editNotifications = new EditableNotifications(savedNotifications);

        securitySettings = await securityTask;

        savedAppearance = await appearanceTask;
        editAppearance = new EditableAppearance(savedAppearance);
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    // === Profile ===
    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile!.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        editProfile = new EditableProfile(savedProfile!);
        ShowToast("Changes discarded.", "toast-info");
    }

    // === Notifications ===
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications!.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications!.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        savedNotifications = prefs;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // === Security ===
    private async Task UpdatePassword()
    {
        passwordError = null;
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelOpen = false;
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Password updated successfully!", "toast-success");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        sessionToRevoke = null;
        ShowToast("Session revoked.", "toast-success");
    }

    // === Appearance ===
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editAppearance!.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        savedAppearance = settings;
        ShowToast("Appearance settings saved!", "toast-success");
    }

    private string GetPreviewFontSize() => editAppearance?.FontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    // === Toast ===
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        toastTimer?.Dispose();
        toastTimer = new System.Timers.Timer(3000);
        toastTimer.Elapsed += (_, _) =>
        {
            toastMessage = null;
            InvokeAsync(StateHasChanged);
            toastTimer?.Dispose();
        };
        toastTimer.AutoReset = false;
        toastTimer.Start();
    }

    public void Dispose()
    {
        toastTimer?.Dispose();
    }

    // === Editable models ===
    private class EditableProfile
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public EditableProfile(UserProfile profile)
        {
            DisplayName = profile.DisplayName;
            Email = profile.Email;
            AvatarUrl = profile.AvatarUrl;
            Bio = profile.Bio;
        }
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public EditableNotifications(NotificationPrefs prefs)
        {
            EmailNotifications = prefs.EmailNotifications;
            PushNotifications = prefs.PushNotifications;
            WeeklyDigest = prefs.WeeklyDigest;
            MutedChannels = new List<string>(prefs.MutedChannels);
        }
    }

    private class EditableAppearance
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public EditableAppearance(AppearanceSettings settings)
        {
            Theme = settings.Theme;
            FontSize = settings.FontSize;
            Language = settings.Language;
            CompactMode = settings.CompactMode;
        }
    }
}

.settings-container {
