    font-size: 0.9rem;
    transition: background 0.2s;
}

.btn-secondary:hover {
    background: #f5f5f5;
}

.btn-danger {
    padding: 0.6rem 1.25rem;
    background: #d32f2f;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
