                    <label><input type="radio" name="fontSize" value="Small" checked="@(editAppearance.FontSize == "Small")" @onchange='() => editAppearance.FontSize = "Small"' /> Small</label>
                    <label><input type="radio" name="fontSize" value="Medium" checked="@(editAppearance.FontSize == "Medium")" @onchange='() => editAppearance.FontSize = "Medium"' /> Medium</label>
                    <label><input type="radio" name="fontSize" value="Large" checked="@(editAppearance.FontSize == "Large")" @onchange='() => editAppearance.FontSize = "Large"' /> Large</label>
